pub trait Colleague { fn receive(&mut self, event: &Event); }

pub struct Mediator { peers: Vec<Rc<RefCell<dyn Colleague>>> }

impl Mediator {
    pub fn notify(&self, from: usize, event: Event) {
        for (i, peer) in self.peers.iter().enumerate() {
            if i != from { peer.borrow_mut().receive(&event); }
        }
    }
}
